test("ajuste: recuento mayor agrega un ingreso por la diferencia", () => {
  const antes = conIngreso();
  const despues = ajustarInventario(antes, { articulo: "A1", almacen: "LPZ", cantidadContada: 14, motivo: "recuento anual" });
  assert.equal(antes.length, 1);
  assert.equal(despues.length, 2);
  assert.deepEqual(despues[1], { tipo: "ingreso", articulo: "A1", almacen: "LPZ", cantidad: 4, motivo: "recuento anual" });
  assert.equal(stock(despues, "A1", "LPZ"), 14);
});

test("ajuste: recuento menor agrega un egreso por la diferencia", () => {
  const despues = ajustarInventario(conIngreso(), { articulo: "A1", almacen: "LPZ", cantidadContada: 0, motivo: "merma" });
  assert.equal(despues.length, 2);
  assert.equal(despues[1].tipo, "egreso");
  assert.equal(despues[1].cantidad, 10);
  assert.equal(stock(despues, "A1", "LPZ"), 0);
});

test("ajuste: sin diferencia no agrega nada", () => {
  const antes = conIngreso();
  const despues = ajustarInventario(antes, { articulo: "A1", almacen: "LPZ", cantidadContada: 10, motivo: "recuento" });
  assert.equal(despues.length, 1);
  assert.deepEqual([...despues], [...antes]);
});

test("ajuste: entradas inválidas se rechazan", () => {
  const base = { articulo: "A1", almacen: "LPZ", cantidadContada: 5, motivo: "recuento" };
  assert.throws(() => ajustarInventario(conIngreso(), { ...base, cantidadContada: -1 }), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), { ...base, cantidadContada: 1.5 }), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), { ...base, motivo: "" }), /motivo/);
});
